```java
import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * 费用计算工具类（纯 Java，无外部依赖）。
 *
 * 规则来源：本次明确需求。
 * - 配送费：itemCount == 0 返回 0；itemCount > 0 且 amount > 200 返回 0；其余合法情况返回 12。
 * - 服务费：amount == 0 返回 0；0 < amount <= 100 返回 2；amount > 100 返回 5。
 * - 金额单位为元，返回值统一保留 2 位小数，不修改输入 BigDecimal。
 */
public final class FeeCalculator {

    private static final BigDecimal ZERO = new BigDecimal("0.00");
    private static final BigDecimal DELIVERY_FEE = new BigDecimal("12.00");
    private static final BigDecimal SERVICE_FEE_LOW = new BigDecimal("2.00");
    private static final BigDecimal SERVICE_FEE_HIGH = new BigDecimal("5.00");

    /** 配送费免配送阈值：严格大于 200 才免配送。 */
    private static final BigDecimal DELIVERY_FREE_THRESHOLD = new BigDecimal("200");

    /** 服务费分档阈值：严格大于 100 进入高档。 */
    private static final BigDecimal SERVICE_HIGH_THRESHOLD = new BigDecimal("100");

    private FeeCalculator() {
        // 工具类，禁止实例化
    }

    /**
     * 计算配送费。
     *
     * @param amount    订单金额（元），不能为 null 且必须 >= 0
     * @param itemCount 件数，不能小于 0
     * @return 配送费，保留 2 位小数
     * @throws IllegalArgumentException 当 amount 为 null、amount < 0 或 itemCount < 0
     */
    public static BigDecimal deliveryFee(BigDecimal amount, int itemCount) {
        // 分别校验：金额与件数各自独立校验
        validateAmount(amount);
        validateItemCount(itemCount);

        // itemCount == 0 返回 0
        if (itemCount == 0) {
            return ZERO;
        }

        // itemCount > 0 且 amount > 200 免配送费
        if (amount.compareTo(DELIVERY_FREE_THRESHOLD) > 0) {
            return ZERO;
        }

        // 其余合法情况（含 amount == 200）返回 12
        return DELIVERY_FEE;
    }

    /**
     * 计算服务费。
     *
     * @param amount 订单金额（元），不能为 null 且必须 >= 0
     * @return 服务费，保留 2 位小数
     * @throws IllegalArgumentException 当 amount 为 null 或 amount < 0
     */
    public static BigDecimal serviceFee(BigDecimal amount) {
        // 服务费独立校验，不使用配送费的件数与 200 阈值
        validateAmount(amount);

        // amount == 0 返回 0
        if (amount.compareTo(BigDecimal.ZERO) == 0) {
            return ZERO;
        }

        // 0 < amount <= 100 返回 2
        if (amount.compareTo(SERVICE_HIGH_THRESHOLD) <= 0) {
            return SERVICE_FEE_LOW;
        }

        // amount > 100 返回 5
        return SERVICE_FEE_HIGH;
    }

    /** 金额校验：非 null 且 >= 0。 */
    private static void validateAmount(BigDecimal amount) {
        if (amount == null) {
            throw new IllegalArgumentException("amount 不能为 null");
        }
        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("amount 不能为负数: " + amount);
        }
    }

    /** 件数校验：>= 0。 */
    private static void validateItemCount(int itemCount) {
        if (itemCount < 0) {
            throw new IllegalArgumentException("itemCount 不能为负数: " + itemCount);
        }
    }
}
```

### 2. FeeCalculatorTest.java（独立测试类，main + 断言）

```java
import java.math.BigDecimal;

/**
 * FeeCalculator 独立测试类，使用 main + 断言，不依赖测试框架。
 * 覆盖正常、异常、边界场景。
 */
public class FeeCalculatorTest {

    private static int passed = 0;
    private static int failed = 0;

    public static void main(String[] args) {
        // ---------- 配送费：正常与边界 ----------
        // itemCount == 0 返回 0（金额任意合法值）
        assertDelivery("delivery itemCount=0, amount=0", "0.00", "0", 0);
        assertDelivery("delivery itemCount=0, amount=200", "0.00", "200", 0);
        assertDelivery("delivery itemCount=0, amount=1000", "0.00", "1000", 0);

        // itemCount > 0 且 amount > 200 免配送
        assertDelivery("delivery amount=200.01, count=1", "0.00", "200.01", 1);
        assertDelivery("delivery amount=201, count=1", "0.00", "201", 1);
        assertDelivery("delivery amount=1000, count=5", "0.00", "1000", 5);

        // amount == 200 不免配送，返回 12
        assertDelivery("delivery amount=200, count=1", "12.00", "200", 1);

        // 阈值下相邻金额
        assertDelivery("delivery amount=199.99, count=1", "12.00", "199.99", 1);
        assertDelivery("delivery amount=100, count=1", "12.00", "100", 1);
        assertDelivery("delivery amount=0.01, count=1", "12.00", "0.01", 1);
        assertDelivery("delivery amount=0, count=1", "12.00", "0", 1);

        // ---------- 服务费：正常与边界 ----------
        // amount == 0 返回 0
        assertService("service amount=0", "0.00", "0");

        // 0 < amount <= 100 返回 2
        assertService("service amount=0.01", "2.00", "0.01");
        assertService("service amount=100", "2.00", "100");
        assertService("service amount=99.99", "2.00", "99.99");

        // amount > 100 返回 5
        assertService("service amount=100.01", "5.00", "100.01");
        assertService("service amount=101", "5.00", "101");
        assertService("service amount=1000", "5.00", "1000");

        // 服务费不使用 200 阈值：amount=200 仍按 >100 返回 5
        assertService("service amount=200", "5.00", "200");

        // ---------- 异常场景 ----------
        // amount 为 null
        assertThrows("delivery null amount", () -> FeeCalculator.deliveryFee(null, 1));
        assertThrows("service null amount", () -> FeeCalculator.serviceFee(null));

        // amount 为负
        assertThrows("delivery negative amount", () -> FeeCalculator.deliveryFee(new BigDecimal("-0.01"), 1));
        assertThrows("service negative amount", () -> FeeCalculator.serviceFee(new BigDecimal("-1")));

        // itemCount 为负
        assertThrows("delivery negative itemCount", () -> FeeCalculator.deliveryFee(new BigDecimal("10"), -1));

        // ---------- 输入 BigDecimal 不被修改 ----------
        BigDecimal input = new BigDecimal("200.00");
        BigDecimal before = new BigDecimal(input.toPlainString());
        FeeCalculator.deliveryFee(input, 1);
        FeeCalculator.serviceFee(input);
        if (input.compareTo(before) == 0) {
            pass("input BigDecimal not modified");
        } else {
            fail("input BigDecimal was modified: " + input);
        }

        // ---------- 返回值保留 2 位小数 ----------
        BigDecimal d = FeeCalculator.deliveryFee(new BigDecimal("50"), 1);
        if (d.scale() == 2) {
            pass("delivery fee scale == 2");
        } else {
            fail("delivery fee scale != 2: " + d.scale());
        }
        BigDecimal s = FeeCalculator.serviceFee(new BigDecimal("50"));
        if (s.scale() == 2) {
            pass("service fee scale == 2");
        } else {
            fail("service fee scale != 2: " + s.scale());
        }

        // ---------- 汇总 ----------
        System.out.println("========================================");
        System.out.println("通过: " + passed + ", 失败: " + failed);
        if (failed > 0) {
            System.out.println("测试失败");
            System.exit(1);
        } else {
            System.out.println("全部测试通过");
        }
    }

    // ---------- 辅助方法 ----------

    private static void assertDelivery(String name, String expected, String amount, int itemCount) {
        try {
            BigDecimal actual = FeeCalculator.deliveryFee(new BigDecimal(amount), itemCount);
            if (actual.compareTo(new BigDecimal(expected)) == 0) {
                pass(name + " -> " + actual);
            } else {
                fail(name + " expected=" + expected + " actual=" + actual);
            }
        } catch (Exception e) {
            fail(name + " threw " + e);
        }
    }

    private static void assertService(String name, String expected, String amount) {
        try {
            BigDecimal actual = FeeCalculator.serviceFee(new BigDecimal(amount));
            if (actual.compareTo(new BigDecimal(expected)) == 0) {
                pass(name + " -> " + actual);
            } else {
                fail(name + " expected=" + expected + " actual=" + actual);
            }
        } catch (Exception e) {
            fail(name + " threw " + e);
        }
    }

    private static void assertThrows(String name, Runnable action) {
        try {
            action.run();
            fail(name + " expected IllegalArgumentException but none thrown");
        } catch (IllegalArgumentException e) {
            pass(name + " threw IllegalArgumentException: " + e.getMessage());
        } catch (Exception e) {
            fail(name + " threw unexpected " + e);
        }
    }

    private static void pass(String msg) {
        passed++;
        System.out.println("[PASS] " + msg);
    }

    private static void fail(String msg) {
        failed++;
        System.out.println("[FAIL] " + msg);
    }
}
