        assertDeliveryFeeThrows(null, 1, "amount must not be null");
        assertDeliveryFeeThrows(null, 0, "amount must not be null");

        // 异常：amount 为负数
        assertDeliveryFeeThrows(new BigDecimal("-0.01"), 1, "amount must be >= 0");
        assertDeliveryFeeThrows(new BigDecimal("-100.00"), 0, "amount must be >= 0");

        // 异常：itemCount 为负数
        assertDeliveryFeeThrows(new BigDecimal("100.00"), -1, "itemCount must be >= 0");
        assertDeliveryFeeThrows(new BigDecimal("0.00"), -1, "itemCount must be >= 0");
    }

