import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * 配送费与服务费计算器。
 *
 * 规则来源：用户明确需求，并与 docs/费用规则.md 一致。
 *
 * 金额单位：元，使用 BigDecimal，返回值统一保留 2 位小数。
 * 输入金额不能为 null 且必须 >= 0；件数不能 < 0；非法输入抛 IllegalArgumentException。
 * 不修改输入 BigDecimal。
 */
public final class FeeCalculator {

    /** 配送费免配送阈值：订单金额严格大于 200 时免配送。 */
    private static final BigDecimal DELIVERY_FREE_THRESHOLD = new BigDecimal("200");

    /** 配送费标准金额。 */
    private static final BigDecimal DELIVERY_FEE = new BigDecimal("12");

    /** 服务费分界阈值：订单金额严格大于 100 时返回 5。 */
    private static final BigDecimal SERVICE_HIGH_THRESHOLD = new BigDecimal("100");

    /** 服务费低档金额。 */
    private static final BigDecimal SERVICE_FEE_LOW = new BigDecimal("2");

    /** 服务费高档金额。 */
    private static final BigDecimal SERVICE_FEE_HIGH = new BigDecimal("5");

    /** 金额统一保留 2 位小数。 */
    private static final int SCALE = 2;

    private FeeCalculator() {
        // 工具类，禁止实例化
    }

    /**
     * 计算配送费。
     *
     * 规则：
     * - itemCount == 0：返回 0；
     * - itemCount > 0 且 amount > 200：返回 0；
     * - 其他情况（含 amount == 200）：返回 12。
     *
     * @param amount    订单金额，不能为 null 且必须 >= 0
     * @param itemCount 件数，不能 < 0
     * @return 配送费，保留 2 位小数
     * @throws IllegalArgumentException 输入非法时抛出
     */
    public static BigDecimal deliveryFee(BigDecimal amount, int itemCount) {
        validateAmount(amount);
        validateItemCount(itemCount);

        // 件数为 0：配送费为 0
        if (itemCount == 0) {
            return scale(DELIVERY_FEE.zero());
        }

        // 件数 > 0 且金额严格大于 200：免配送
        if (amount.compareTo(DELIVERY_FREE_THRESHOLD) > 0) {
            return scale(DELIVERY_FEE.zero());
        }

        // 其他情况（含金额恰好 200）：配送费 12
        return scale(DELIVERY_FEE);
    }

    /**
     * 计算服务费。
     *
     * 规则：
     * - amount == 0：返回 0；
     * - 0 < amount <= 100：返回 2；
     * - amount > 100：返回 5。
     *
     * 注意：服务费不使用配送费的 200 阈值。
     *
     * @param amount 订单金额，不能为 null 且必须 >= 0
     * @return 服务费，保留 2 位小数
     * @throws IllegalArgumentException 输入非法时抛出
     */
    public static BigDecimal serviceFee(BigDecimal amount) {
        validateAmount(amount);

        // 金额为 0：服务费为 0
        if (amount.compareTo(BigDecimal.ZERO) == 0) {
            return scale(SERVICE_FEE_LOW.zero());
        }

        // 金额严格大于 100：服务费 5
        if (amount.compareTo(SERVICE_HIGH_THRESHOLD) > 0) {
            return scale(SERVICE_FEE_HIGH);
        }

        // 0 < amount <= 100：服务费 2
        return scale(SERVICE_FEE_LOW);
    }

    /**
     * 校验金额：不能为 null 且必须 >= 0。
     */
    private static void validateAmount(BigDecimal amount) {
        if (amount == null) {
            throw new IllegalArgumentException("金额不能为 null");
        }
        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("金额不能小于 0，实际值：" + amount);
        }
    }

    /**
     * 校验件数：不能 < 0。
     */
    private static void validateItemCount(int itemCount) {
        if (itemCount < 0) {
            throw new IllegalArgumentException("件数不能小于 0，实际值：" + itemCount);
        }
    }

    /**
     * 统一保留 2 位小数，不修改原对象。
     */
    private static BigDecimal scale(BigDecimal value) {
        return value.setScale(SCALE, RoundingMode.HALF_UP);
    }
}
