        assertThrows("服务费-负金额-整数", () -> FeeCalculator.serviceFee(new BigDecimal("-100")));

        // ==================== 不修改输入 BigDecimal 测试 ====================

        BigDecimal input = new BigDecimal("200.005");
        BigDecimal before = new BigDecimal(input.toPlainString());
        FeeCalculator.deliveryFee(input, 1);
        FeeCalculator.serviceFee(input);
        if (input.compareTo(before) == 0) {
            pass("不修改输入-BigDecimal");
        } else {
            fail("不修改输入-BigDecimal", "输入被修改：" + before + " -> " + input);
        }

        // ==================== 返回值 2 位小数测试 ====================

        assertScale("配送费-2位小数", FeeCalculator.deliveryFee(new BigDecimal("100"), 1));
        assertScale("服务费-2位小数", FeeCalculator.serviceFee(new BigDecimal("100")));

        // ==================== 汇总 ====================

        System.out.println("========================================");
        System.out.println("测试通过：" + passed + "，失败：" + failed);
        if (failed > 0) {
            System.out.println("存在失败用例！");
            System.exit(1);
        } else {
            System.out.println("全部测试通过。");
        }
    }

    // ---------- 断言辅助方法 ----------

    private static void assertDelivery(String name, String expected, String amount, int itemCount) {
        try {
            BigDecimal actual = FeeCalculator.deliveryFee(new BigDecimal(amount), itemCount);
            BigDecimal exp = new BigDecimal(expected);
            if (actual.compareTo(exp) == 0 && actual.scale() == 2) {
                pass(name);
            } else {
                fail(name, "期望 " + expected + "（2位小数），实际 " + actual + "（scale=" + actual.scale() + "）");
            }
        } catch (Exception e) {
            fail(name, "抛出异常：" + e);
        }
    }

    private static void assertService(String name, String expected, String amount) {
        try {
            BigDecimal actual = FeeCalculator.serviceFee(new BigDecimal(amount));
            BigDecimal exp = new BigDecimal(expected);
            if (actual.compareTo(exp) == 0 && actual.scale() == 2) {
                pass(name);
            } else {
                fail(name, "期望 " + expected + "（2位小数），实际 " + actual + "（scale=" + actual.scale() + "）");
            }
        } catch (Exception e) {
            fail(name, "抛出异常：" + e);
        }
    }

    private static void assertThrows(String name, Runnable action) {
        try {
            action.run();
            fail(name, "期望抛出 IllegalArgumentException，但未抛出");
        } catch (IllegalArgumentException e) {
            pass(name);
        } catch (Exception e) {
            fail(name, "期望 IllegalArgumentException，实际抛出 " + e.getClass().getName());
        }
    }

    private static void assertScale(String name, BigDecimal value) {
        if (value.scale() == 2) {
            pass(name);
        } else {
            fail(name, "期望 scale=2，实际 scale=" + value.scale());
        }
    }

    private static void pass(String name) {
        passed++;
        System.out.println("[PASS] " + name);
    }

    private static void fail(String name, String message) {
        failed++;
        System.out.println("[FAIL] " + name + " -> " + message);
    }
}
